<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('siswa');$uid=(int)currentUser()['id_user'];$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();try{$lid=(int)($_POST['id_laporan']??0);$bukti=trim($_POST['bukti']??'');if(!$lid||strlen($bukti)<10)throw new Exception('Bukti kepemilikan harus dijelaskan minimal 10 karakter.');$s=$koneksi->prepare("SELECT id_user FROM laporan WHERE id_laporan=? AND jenis_laporan='ditemukan' AND moderation_status='aktif' AND status IN ('menunggu','diproses')");$s->bind_param('i',$lid);$s->execute();if(!$s->get_result()->num_rows)throw new Exception('Barang tidak tersedia untuk diklaim.');$s=$koneksi->prepare("SELECT id_klaim FROM klaim WHERE id_laporan=? AND id_user=? AND status_klaim IN ('menunggu','disetujui')");$s->bind_param('ii',$lid,$uid);$s->execute();if($s->get_result()->num_rows)throw new Exception('Kamu sudah mengajukan klaim untuk barang ini.');$s=$koneksi->prepare('INSERT INTO klaim(id_laporan,id_user,bukti_kepemilikan) VALUES(?,?,?)');$s->bind_param('iis',$lid,$uid,$bukti);$s->execute();$admins=$koneksi->query("SELECT id_user FROM users WHERE role='admin'");while($a=$admins->fetch_assoc())notifyUser($koneksi,(int)$a['id_user'],'Klaim barang baru','Ada klaim baru yang perlu diperiksa.','admin/klaim.php');logActivity($koneksi,$uid,'Mengajukan klaim','Laporan #'.$lid);flash('Klaim berhasil diajukan. Tunggu verifikasi admin.');redirect('siswa/klaim.php');}catch(Throwable $e){$err=$e->getMessage();}}
$pageTitle='Klaim Saya';require __DIR__.'/../includes/header.php';if(isset($_GET['id'])){$lid=(int)$_GET['id'];$s=$koneksi->prepare("SELECT l.*,lo.nama_lokasi,k.nama_kategori FROM laporan l JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi JOIN kategori k ON k.id_kategori=l.id_kategori WHERE l.id_laporan=? AND l.jenis_laporan='ditemukan' AND l.moderation_status='aktif'");$s->bind_param('i',$lid);$s->execute();$item=$s->get_result()->fetch_assoc();?><div class="panel" style="max-width:760px"><h2>Ajukan klaim barang</h2><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><?php if(!$item):?><div class="empty">Barang tidak ditemukan.</div><?php else:?><div class="item"><div class="item-thumb"></div><div class="item-info"><b><?=e($item['nama_barang'])?></b><small><?=e($item['nama_kategori'])?> · <?=e($item['nama_lokasi'])?></small></div></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id_laporan" value="<?=$lid?>"><div class="field"><label>Bukti kepemilikan *</label><textarea name="bukti" required placeholder="Jelaskan ciri khusus barang, isi, merek, atau bukti lain yang dapat memastikan kepemilikan..."></textarea></div><button class="btn">Kirim klaim</button></form><?php endif;?></div><?php }else{$s=$koneksi->prepare('SELECT k.*,l.nama_barang,l.foto_barang FROM klaim k JOIN laporan l ON l.id_laporan=k.id_laporan WHERE k.id_user=? ORDER BY k.created_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();?><div class="panel"><div class="panel-head"><h2>Riwayat klaim saya</h2><a class="btn secondary sm" href="barang.php">Cari barang temuan</a></div><?php if(!$rows->num_rows):?><div class="empty"><div class="big"></div>Belum ada klaim barang.</div><?php endif;?><div class="table-wrap"><table><tr><th>Barang</th><th>Tanggal</th><th>Status</th><th>Catatan admin</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?></td><td><?=e(date('d/m/Y',strtotime($r['created_at'])))?></td><td><span class="badge <?=e($r['status_klaim'])?>"><?=e(statusLabel($r['status_klaim']))?></span></td><td><?=e($r['catatan_admin']??'-')?></td></tr><?php endwhile;?></table></div></div><?php }require __DIR__.'/../includes/footer.php';?>
